import React, { useState, useEffect } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/LanguageContext';
import { apiService } from '../../services/api';
import FixerPaymentManager from '../Payment/FixerPaymentManager';
import LanguageSelector from '../Common/LanguageSelector';
import Logo from '../Common/Logo';

const Profile = () => {
  const { user } = useAuth();
  const { t } = useLanguage();
  const [fixer, setFixer] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('profile');
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({
    first_name: '',
    last_name: '',
    email: '',
    address: ''
  });

  useEffect(() => {
    // Initialize edit data with current user data
    if (user) {
      setEditData({
        first_name: user.first_name || '',
        last_name: user.last_name || '',
        email: user.email || '',
        address: user.address || ''
      });
    }

    // Check if user is also a fixer
    const fetchFixerData = async () => {
      try {
        if (user?.phone) {
          const fixers = await apiService.getFixers();
          const userFixer = fixers.data?.find(f => f.phone === user.phone);
          setFixer(userFixer);
        }
      } catch (error) {
        console.error('Error fetching fixer data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchFixerData();
  }, [user]);

  const handleEditToggle = () => {
    setIsEditing(!isEditing);
    if (!isEditing && user) {
      // Reset edit data when entering edit mode
      setEditData({
        first_name: user.first_name || '',
        last_name: user.last_name || '',
        email: user.email || '',
        address: user.address || ''
      });
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setEditData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSaveProfile = async () => {
    try {
      setLoading(true);
      // API call to update user profile would go here
      // For now, just toggle edit mode off
      setIsEditing(false);
      // TODO: Add actual API call to update user profile
      console.log('Profile update data:', editData);
    } catch (error) {
      console.error('Error updating profile:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      {/* Profile Header */}
      <div className="bg-white rounded-lg shadow-sm p-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center">
              <span className="text-white text-2xl font-bold">
                {user?.first_name?.charAt(0)?.toUpperCase() || user?.name?.charAt(0)?.toUpperCase()}
              </span>
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">
                {user?.full_name || `${user?.first_name || ''} ${user?.last_name || ''}`.trim() || user?.name}
              </h1>
              <p className="text-gray-600">{user?.phone}</p>
              {fixer && (
                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                  {t('fixer', 'Fixer')} • Rating: {fixer.rating.toFixed(1)}⭐
                </span>
              )}
            </div>
          </div>

          <div className="flex items-center space-x-4">
            <LanguageSelector />
            {isEditing ? (
              <div className="flex space-x-2">
                <button 
                  onClick={handleSaveProfile}
                  className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700"
                >
                  {t('saveChanges', 'Save Changes')}
                </button>
                <button 
                  onClick={handleEditToggle}
                  className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700"
                >
                  {t('cancel', 'Cancel')}
                </button>
              </div>
            ) : (
              <button 
                onClick={handleEditToggle}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                {t('editProfile', 'Edit Profile')}
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Profile Tabs */}
      <div className="bg-white rounded-lg shadow-sm">
        <div className="border-b border-gray-200">
          <nav className="-mb-px flex space-x-8 px-6">
            <button
              onClick={() => setActiveTab('profile')}
              className={`py-4 px-1 border-b-2 font-medium text-sm ${
                activeTab === 'profile'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              {t('profile', 'Profile')}
            </button>

            {fixer && (
              <>
                <button
                  onClick={() => setActiveTab('payments')}
                  className={`py-4 px-1 border-b-2 font-medium text-sm ${
                    activeTab === 'payments'
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  {t('payments', 'Payments')}
                </button>

                <button
                  onClick={() => setActiveTab('verification')}
                  className={`py-4 px-1 border-b-2 font-medium text-sm ${
                    activeTab === 'verification'
                      ? 'border-blue-500 text-blue-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  {t('verification', 'Verification')}
                </button>
              </>
            )}

            <button
              onClick={() => setActiveTab('settings')}
              className={`py-4 px-1 border-b-2 font-medium text-sm ${
                activeTab === 'settings'
                  ? 'border-blue-500 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
              }`}
            >
              {t('settings', 'Settings')}
            </button>
          </nav>
        </div>

        <div className="p-6">
          {activeTab === 'profile' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <h3 className="text-lg font-medium mb-4">
                    {t('personalInfo', 'Personal Information')}
                  </h3>
                  <div className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700">
                          {t('firstName', 'First Name')}
                        </label>
                        {isEditing ? (
                          <input
                            type="text"
                            name="first_name"
                            value={editData.first_name}
                            onChange={handleInputChange}
                            className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                            required
                          />
                        ) : (
                          <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                            {user?.first_name || t('notProvided', 'Not provided')}
                          </div>
                        )}
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700">
                          {t('lastName', 'Last Name')}
                        </label>
                        {isEditing ? (
                          <input
                            type="text"
                            name="last_name"
                            value={editData.last_name}
                            onChange={handleInputChange}
                            className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                            required
                          />
                        ) : (
                          <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                            {user?.last_name || t('notProvided', 'Not provided')}
                          </div>
                        )}
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        {t('phoneNumber', 'Phone Number')}
                      </label>
                      <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                        {user?.phone}
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        {t('idNumber', 'ID Number')}
                      </label>
                      <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                        {user?.id_number || t('notProvided', 'Not provided')}
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        {t('town', 'Town/Municipality')}
                      </label>
                      <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                        {user?.town || t('notProvided', 'Not provided')}
                      </div>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        {t('email', 'Email')}
                      </label>
                      {isEditing ? (
                        <input
                          type="email"
                          name="email"
                          value={editData.email}
                          onChange={handleInputChange}
                          className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                        />
                      ) : (
                        <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                          {user?.email || t('notProvided', 'Not provided')}
                        </div>
                      )}
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700">
                        {t('address', 'Address')}
                      </label>
                      {isEditing ? (
                        <textarea
                          name="address"
                          value={editData.address}
                          onChange={handleInputChange}
                          rows={3}
                          className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
                        />
                      ) : (
                        <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                          {user?.address || t('notProvided', 'Not provided')}
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {fixer && (
                  <div>
                    <h3 className="text-lg font-medium mb-4">
                      {t('fixerInfo', 'Fixer Information')}
                    </h3>
                    <div className="space-y-4">
                      <div>
                        <label className="block text-sm font-medium text-gray-700">
                          {t('services', 'Services')}
                        </label>
                        <div className="mt-1">
                          {JSON.parse(fixer.services).map((service, index) => (
                            <span
                              key={index}
                              className="inline-block bg-blue-100 text-blue-800 text-sm px-2 py-1 rounded mr-2 mb-2"
                            >
                              {service}
                            </span>
                          ))}
                        </div>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700">
                          {t('location', 'Location')}
                        </label>
                        <div className="mt-1 p-3 bg-gray-50 border border-gray-200 rounded-md">
                          {fixer.location}
                        </div>
                      </div>
                      <div>
                        <label className="block text-sm font-medium text-gray-700">
                          {t('statistics', 'Statistics')}
                        </label>
                        <div className="mt-1 grid grid-cols-3 gap-4">
                          <div className="bg-green-50 p-3 rounded-md text-center">
                            <div className="text-2xl font-bold text-green-600">
                              {fixer.rating.toFixed(1)}
                            </div>
                            <div className="text-sm text-gray-600">
                              {t('rating', 'Rating')}
                            </div>
                          </div>
                          <div className="bg-blue-50 p-3 rounded-md text-center">
                            <div className="text-2xl font-bold text-blue-600">
                              {fixer.total_jobs}
                            </div>
                            <div className="text-sm text-gray-600">
                              {t('totalJobs', 'Total Jobs')}
                            </div>
                          </div>
                          <div className="bg-purple-50 p-3 rounded-md text-center">
                            <div className={`text-2xl font-bold ${
                              fixer.is_active ? 'text-green-600' : 'text-red-600'
                            }`}>
                              {fixer.is_active ? '✓' : '✗'}
                            </div>
                            <div className="text-sm text-gray-600">
                              {t('status', 'Status')}
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === 'payments' && fixer && (
            <div>
              <h3 className="text-lg font-medium mb-4">
                {t('paymentManagement', 'Payment Management')}
              </h3>
              <FixerPaymentManager fixerId={fixer.id} />
            </div>
          )}

          {activeTab === 'verification' && fixer && (
            <div>
              <h3 className="text-lg font-medium mb-4">
                {t('documentVerification', 'Document Verification')}
              </h3>
              <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
